<template><section class="page"><h2>我的货运单</h2><van-loading v-if="loading"/><div v-for="order in orders" :key="order.orderNo" class="card"><b>{{ order.orderNo }}</b><p class="money">{{ order.payAmount }}</p><p class="note">{{ label(order.orderStatus) }} · {{ order.createTime }}</p><van-button v-if="order.orderStatus===0" size="small" plain type="danger" @click="cancel(order.orderNo)">取消订单</van-button><van-button v-if="order.orderStatus===2" size="small" type="primary" @click="confirm(order.orderNo)">确认收货</van-button><van-button v-if="order.orderStatus===2" size="small" plain @click="track(order.orderNo)">物流</van-button></div><van-empty v-if="!loading&&!orders.length" description="还没有订单"/></section></template>
<script setup>
import{ref,onMounted}from'vue';import{showToast}from'vant';import{tradeApi}from'../api'
const orders=ref([]),loading=ref(false);const labels=['待支付','待发货','待收货','已完成','已取消'];const label=s=>labels[s]||'处理中';async function load(){loading.value=true;try{orders.value=(await tradeApi.orders()).data.records||[]}catch(e){showToast(e)}finally{loading.value=false}}async function confirm(orderNo){try{await tradeApi.confirmOrder(orderNo);load()}catch(e){showToast(e)}}async function cancel(orderNo){try{await tradeApi.cancelOrder(orderNo);load()}catch(e){showToast(e)}}async function track(orderNo){try{const data=(await tradeApi.logistics(orderNo)).data;showToast(data?.trackingNo?`物流单号：${data.trackingNo}`:'暂未录入物流信息')}catch(e){showToast(e)}}onMounted(load)
</script>
